(function(root){
function validateScenario(data,plants){if(!data||![1,2].includes(data.version)||!Array.isArray(data.rows)||data.rows.length!==plants.length||typeof data.study!=='string'||typeof data.notes!=='string'||typeof data.participation!=='boolean')throw Error('Formato de cenário CTG inválido.');const ids=new Set(plants.map(p=>p.id)),seen=new Set();data.rows.forEach(r=>{if(!ids.has(r.id)||seen.has(r.id)||typeof r.include!=='boolean'||typeof r.edited!=='boolean')throw Error('A lista deve conter cada usina CTG uma única vez.');seen.add(r.id);[r.teif,r.ip].forEach(v=>{if(v===''||v===null||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100)throw Error('TEIF e IP devem estar entre 0 e 100%.')})});return {version:2,configurationVersion:'ctg-unitarias-2026-10-30',study:data.study.slice(0,300),notes:data.notes.slice(0,2000),participation:data.participation,rows:data.rows.map(r=>({id:r.id,include:r.include,teif:Number(r.teif),ip:Number(r.ip),edited:r.edited}))}}
function num(v,label,max=100){if(v===''||v===null||typeof v==='boolean'||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>max)throw Error(label+' inválido');return Number(v)}
function unitRow(u,p){return {id:u.id,mw:u.mw,teif:u.teif??p.teif,ip:u.ip??p.ip,include:u.include!==false}}
function initial(plants,units,cfg={}){return {version:3,configurationVersion:'ctg-ugs-v3',study:cfg.study||'CTG Brasil · cenário '+(cfg.year||2027),notes:cfg.notes||'Manutenção das taxas ONS de setembro/2026',participation:!!cfg.participation,rows:plants.map(p=>({id:p.id,include:p.kind==='participacao'?!!cfg.participation:p.includeDefault!==false,teif:p.teif,ip:p.ip,edited:false})),units:units.filter(u=>u.eligible).map(u=>unitRow(u,plants.find(p=>p.id===u.plantId)))}}
function validateUnits(data,plants,units,cfg={}){
 if(data?.version!==3){const old=validateScenario(data,plants),next=initial(plants,units,cfg);Object.assign(next,{study:old.study,notes:old.notes,participation:old.participation,rows:old.rows});for(const u of next.units){const p=units.find(x=>x.id===u.id),r=old.rows.find(x=>x.id===p.plantId);if(r.edited||data.configurationVersion!=='sheets-v3'){u.teif=r.teif;u.ip=r.ip}}return next}
 const checked=validateScenario({...data,version:2},plants),eligible=units.filter(u=>u.eligible),ids=new Set(eligible.map(u=>u.id)),seen=new Set();if(!Array.isArray(data.units)||data.units.length!==eligible.length)throw Error('Cadastro de UGs do cenário incompatível.');
 const rows=data.units.map(u=>{if(!ids.has(u.id)||seen.has(u.id)||typeof u.include!=='boolean')throw Error('UG inválida ou duplicada: '+u.id);seen.add(u.id);const mw=num(u.mw,'Potência',1300);if(mw<=0)throw Error('Potência deve ser positiva');return {id:u.id,mw,teif:num(u.teif,'TEIF'),ip:num(u.ip,'IP'),include:u.include}});
 return {...checked,version:3,configurationVersion:'ctg-ugs-v3',units:rows};
}
function summarize(state,plants,units,refs){
 const availability=(t,i)=>100*(1-num(t,'TEIF')/100)*(1-num(i,'IP')/100);
 const flat=state.units.map(r=>{const u=units.find(u=>u.id===r.id),p=state.rows.find(p=>p.id===u.plantId),plant=plants.find(p=>p.id===u.plantId);let disp=null,refDisp=null,band=null;try{num(r.mw,'Potência',1300);if(r.mw<=0)throw Error();band=refs.findIndex(b=>r.mw<=b[0])+1;if(!band)throw Error();disp=availability(r.teif,r.ip);refDisp=availability(refs[band-1][1],refs[band-1][2])}catch(e){}return {...u,...r,rateOrigin:r.teif!==u.teif||r.ip!==u.ip?'Cenário editado':u.rateOrigin,band,disp,refDisp,selected:!!(r.include&&p.include&&(plant.kind==='operada'||state.participation))}});
 const details=plants.map(p=>{const r=state.rows.find(r=>r.id===p.id),all=flat.filter(u=>u.plantId===p.id),included=all.filter(u=>u.include),valid=included.every(u=>u.disp!==null),power=included.reduce((s,u)=>s+Number(u.mw||0),0),weighted=k=>power?included.reduce((s,u)=>s+u.mw*u[k],0)/power:null;return {...p,...r,units:all,n:included.length,power,teif:valid?weighted('teif'):null,ip:valid?weighted('ip'):null,disp:valid?weighted('disp'):null,refDisp:valid?weighted('refDisp'):null,unitIds:included.map(u=>u.ug),selected:!!(r.include&&(p.kind==='operada'||state.participation)),bands:[...new Set(included.map(u=>u.band))]}});
 const selected=flat.filter(u=>u.selected),valid=selected.every(u=>u.disp!==null),power=selected.reduce((s,u)=>s+Number(u.mw||0),0),equivalent=selected.reduce((s,u)=>s+u.mw*(u.disp||0)/100,0);
 return {plants:details,units:flat,power,equivalent:valid&&power?equivalent:null,availability:valid&&power?100*equivalent/power:null,unitCount:selected.length,plantCount:details.filter(p=>p.selected&&p.n).length,invalid:selected.filter(u=>u.disp===null).length,bands:refs.map((ref,k)=>{const us=selected.filter(u=>u.band===k+1),ok=us.length&&us.every(u=>u.disp!==null),teif=ok?us.reduce((s,u)=>s+Number(u.teif),0)/us.length:null,ip=ok?us.reduce((s,u)=>s+Number(u.ip),0)/us.length:null;return {plants:new Set(us.map(u=>u.plantId)).size,n:us.length,teif,ip,disp:ok?availability(teif,ip):null}})};
}
const api={validateScenario,initial,validateUnits,summarize};root.CTGModel=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
